{%- comment -%}
Tutorial tabs navigation
- Slim height
- Mobile horizontal scroll (guaranteed via inner max-content)
- No borders
- Background: #F0E4D4
{%- endcomment -%}

<div class="cozy-tutorial-tabs" role="navigation" aria-label="Tutorial sections">
  <div class="cozy-tutorial-tabs__inner">
    <a class="cozy-tutorial-tab" href="#shopify-section-template--22811779924286__rich_text_yHGdwE">
      Drapery Tutorials
    </a>

    <span class="cozy-tutorial-sep" aria-hidden="true"></span>

    <a class="cozy-tutorial-tab" href="#shopify-section-template--22811779924286__rich_text_3PpHXQ">
      Shades Tutorials
    </a>

    <span class="cozy-tutorial-sep" aria-hidden="true"></span>

    <a class="cozy-tutorial-tab" href="#shopify-section-template--22811779924286__rich_text_MMYpAb">
      Hardware &amp; Accessories
    </a>
  </div>
</div>

<style>
      #shopify-section-template--22811779924286__custom_liquid_9WUzUJ {
        position: sticky;
        top: 132px;
        z-index: 400;
      }
      @media (max-width: 749px) {
                #shopify-section-template--22811779924286__custom_liquid_9WUzUJ {
          top: 88px;
        }
      }
      @media (min-width: 750px) and (max-width: 1199px) {
        #shopify-section-template--22811779924286__custom_liquid_9WUzUJ {
          top: 259px;
        }
      }
      @media (min-width: 1200px) {
        #shopify-section-template--22811779924286__custom_liquid_9WUzUJ {
          top: 132px;
        }
      }
  /* 外层：只负责滚动与背景 */
  .cozy-tutorial-tabs{
    background-color:#F0E4D4;
    padding:10px 12px;          /* 👈 更矮更窄 */
    overflow-x:auto;
    overflow-y:hidden;
    -webkit-overflow-scrolling:touch;
    scrollbar-width:none;

    /* 👇 让手机更“好滑” */
    touch-action: pan-x;
    overscroll-behavior-x: contain;

    width:100%;
  }
  .cozy-tutorial-tabs::-webkit-scrollbar{ display:none; }

  /* 内层：强制按内容宽度展开 -> 一定产生横向溢出 */
  .cozy-tutorial-tabs__inner{
    display:flex;
    align-items:center;
    justify-content:flex-start;

    width:max-content;          /* ✅ 关键：保证可横向滚动 */
    min-width:100%;
  }

  .cozy-tutorial-tab{
    flex:0 0 auto;
    white-space:nowrap;

    padding:8px 110px;           /* 👈 高度更低，左右保持间距 */
    text-decoration:none;
    color:inherit;
    line-height:1.3;
  }

  .cozy-tutorial-sep{
    flex:0 0 auto;
    width:1px;
    height:14px;
    background:rgba(0,0,0,0.25);
    margin:0 10px;
  }

  /* 桌面端：不需要滚动时也能居中显示 */
  @media (min-width: 990px){
    .cozy-tutorial-tabs{
      overflow-x:visible;
    }
    .cozy-tutorial-tabs__inner{
      width:100%;
      justify-content:center;
    }
  }
</style>

<script>
  (function () {
    document.addEventListener('click', function (e) {
      var link = e.target.closest('.cozy-tutorial-tab');
      if (!link) return;

      var hash = link.getAttribute('href');
      if (!hash || hash.charAt(0) !== '#') return;

      var target = document.querySelector(hash);
      if (!target) return;

      e.preventDefault();
      target.scrollIntoView({ behavior: 'smooth', block: 'start' });
      history.pushState(null, '', hash);
    });
  })();
</script>
